// Embedded copy of Images/devil-sword.glb so the model still loads when index.html is opened
// straight from disk (file://), where browsers block fetching the .glb file.
// Regenerate this file if devil-sword.glb is re-exported.
window.EMBEDDED_MODELS = window.EMBEDDED_MODELS || {};
window.EMBEDDED_MODELS["Images/devil-sword.glb"] = "data:model/gltf-binary;base64,";
